{"version":"AzureDataExplorerQuery/1.0","queryText":"let SelectedCurrency = tostring('{BillingCurrency}');
let StartTime = todatetime('{LookbackPeriod:startISO}');
let EndTime = todatetime('{LookbackPeriod:endISO}');
let odcr = Costs()
| where ChargePeriodStart between (StartTime .. EndTime)
| where ProviderName == 'Microsoft'
| where ChargeCategory == 'Usage'
| where isnotempty(CapacityReservationId)
| where CapacityReservationStatus in~ ('Used', 'Unused')
| extend BillingCurrencyCode = tostring(BillingCurrency)
| where isempty(SelectedCurrency) or BillingCurrencyCode =~ SelectedCurrency
| extend Status = case(CapacityReservationStatus =~ 'Unused', 'Unused ODCR', CapacityReservationStatus =~ 'Used', 'Used ODCR', 'Unknown')
| extend CapacityReservationGroupId = tolower(tostring(extract(@'(?i)^(.*/capacityreservationgroups/[^/]+)', 1, CapacityReservationId)));
let totals = odcr
| summarize TotalCost = sum(EffectiveCost), UnusedCost = sumif(EffectiveCost, Status == 'Unused ODCR'), UsedCost = sumif(EffectiveCost, Status == 'Used ODCR'), CRGs = dcount(CapacityReservationGroupId), Reservations = dcount(CapacityReservationId) by Currency = BillingCurrencyCode;
totals
| extend UnusedPercent = iff(TotalCost > 0, UnusedCost / TotalCost * 100.0, 0.0)
| extend Action = case(UnusedCost <= 0, 'No billing waste detected', UnusedPercent >= 25, 'Immediate CRG cleanup review', UnusedPercent >= 10, 'Review workload placement', 'Monitor trend')
| project Currency, Metric = 'Unused ODCR cost', Value = round(UnusedCost, 2), Status = Action
| union (totals | project Currency, Metric = 'Used ODCR cost', Value = round(UsedCost, 2), Status = 'Capacity consumed by associated compute')
| union (totals | extend UnusedPercent = iff(TotalCost > 0, UnusedCost / TotalCost * 100.0, 0.0) | project Currency, Metric = 'Unused percent', Value = round(UnusedPercent, 1), Status = iff(UnusedPercent >= 10, 'Investigate', 'Acceptable'))
| union (totals | project Currency, Metric = 'Capacity reservations', Value = todouble(Reservations), Status = 'Distinct reservations in billing window')
| union (totals | project Currency, Metric = 'Capacity reservation groups', Value = todouble(CRGs), Status = 'Distinct CRG resource IDs in billing window')","clusterName":"{AdxClusterName}","databaseName":"{AdxDatabaseName}"}

{"version":"AzureDataExplorerQuery/1.0","queryText":"let SelectedCurrency = tostring('{BillingCurrency}');
let StartTime = todatetime('{LookbackPeriod:startISO}');
let EndTime = todatetime('{LookbackPeriod:endISO}');
Costs()
| where ChargePeriodStart between (StartTime .. EndTime)
| where ProviderName == 'Microsoft'
| where ChargeCategory == 'Usage'
| where CapacityReservationStatus =~ 'Unused'
| extend BillingCurrencyCode = tostring(BillingCurrency)
| where isempty(SelectedCurrency) or BillingCurrencyCode =~ SelectedCurrency
| summarize UnusedCost = round(sum(EffectiveCost), 2) by Day = startofday(ChargePeriodStart), Currency = BillingCurrencyCode
| order by Day asc, Currency asc","clusterName":"{AdxClusterName}","databaseName":"{AdxDatabaseName}"}

{"version":"AzureDataExplorerQuery/1.0","queryText":"let StartTime = todatetime('{LookbackPeriod:startISO}');
let EndTime = todatetime('{LookbackPeriod:endISO}');
Costs()
| where ChargePeriodStart between (StartTime .. EndTime)
| where ProviderName == 'Microsoft'
| where ChargeCategory == 'Usage'
| summarize Rows = count(), RowsWithCapacityReservationId = countif(isnotempty(CapacityReservationId)), RowsWithCapacityReservationStatus = countif(isnotempty(CapacityReservationStatus)), RowsWithBothFields = countif(isnotempty(CapacityReservationId) and isnotempty(CapacityReservationStatus)), FirstRecord = min(ChargePeriodStart), LastRecord = max(ChargePeriodStart)
| extend ODCRBillingDataStatus = case(RowsWithBothFields > 0, 'ODCR billing fields available', RowsWithCapacityReservationId > 0 or RowsWithCapacityReservationStatus > 0, 'ODCR billing fields partially populated', 'ODCR billing fields not populated')
| project ODCRBillingDataStatus, Rows, RowsWithCapacityReservationId, RowsWithCapacityReservationStatus, RowsWithBothFields, FirstRecord, LastRecord","clusterName":"{AdxClusterName}","databaseName":"{AdxDatabaseName}"}

{"version":"AzureDataExplorerQuery/1.0","queryText":"let SelectedCurrency = tostring('{BillingCurrency}');
let StartTime = todatetime('{LookbackPeriod:startISO}');
let EndTime = todatetime('{LookbackPeriod:endISO}');
let odcr = Costs()
| where ChargePeriodStart between (StartTime .. EndTime)
| where ProviderName == 'Microsoft'
| where ChargeCategory == 'Usage'
| where isnotempty(CapacityReservationId)
| where CapacityReservationStatus in~ ('Used', 'Unused')
| extend BillingCurrencyCode = tostring(BillingCurrency)
| where isempty(SelectedCurrency) or BillingCurrencyCode =~ SelectedCurrency
| extend ODCRStatus = case(CapacityReservationStatus =~ 'Unused', 'Unused ODCR', CapacityReservationStatus =~ 'Used', 'Used ODCR', 'Unknown');
let totals = odcr
| summarize TotalCost = sum(EffectiveCost), UnusedCost = sumif(EffectiveCost, ODCRStatus == 'Unused ODCR'), UsedCost = sumif(EffectiveCost, ODCRStatus == 'Used ODCR'), Reservations = dcount(CapacityReservationId), Resources = dcount(ResourceId) by Currency = BillingCurrencyCode;
totals
| extend UnusedPercent = iff(TotalCost > 0, UnusedCost / TotalCost * 100.0, 0.0)
| project Currency, TotalCost = round(TotalCost, 2), UsedCost = round(UsedCost, 2), UnusedCost = round(UnusedCost, 2), UnusedPercent = round(UnusedPercent, 1), Reservations, Resources","clusterName":"{AdxClusterName}","databaseName":"{AdxDatabaseName}"}

